  viva:[["What are the boundaries of the femoral triangle?","Inguinal ligament above, medial border of sartorius laterally, medial border of adductor longus medially."],["What is the deepest structure in the popliteal fossa?","Popliteal artery."],["What is the keystone of the medial longitudinal arch?","Head of the talus."]],
  refs:[{c:"B D Chaurasia. Human Anatomy, Volume 2: Lower Limb, Abdomen and Pelvis. Chapters: Front of thigh; popliteal fossa; arches of foot."},{c:"Martin RL, Davenport TE, Reischl SF, et al. Heel pain - plantar fasciitis: revision 2014. J Orthop Sports Phys Ther. 2014.", q:"Martin heel pain plantar fasciitis clinical practice guideline 2014 JOSPT"},{b:"neumann",ch:"Ankle and foot: arches"},{b:"magee",ch:"Lower leg, ankle and foot"}],
